import assert from 'node:assert/strict';
import {build} from 'esbuild';
import {readFile,readdir} from 'node:fs/promises';
import path from 'node:path';
import {sha256} from './runtime-lineage.mjs';

/** Compare generated bytes to source, without repairing outputs before checking. */
export async function verifySDKOutputs(root=process.cwd()) {
  const hashes={};
  for(const file of (await readdir(path.join(root,'packages/sdk/src'))).filter(f=>f.endsWith('.d.ts')).sort()) {
    const source=await readFile(path.join(root,'packages/sdk/src',file));
    assert.deepEqual(await readFile(path.join(root,'packages/sdk/dist',file)),source,`declaration drift ${file}`);
    hashes[file]=sha256(source);
  }
  for(const entry of ['index','three']) {
    const output=(await build({absWorkingDir:path.resolve(root),entryPoints:[`packages/sdk/src/${entry}.js`],bundle:true,format:'esm',platform:'browser',external:['three/webgpu'],legalComments:'none',write:false})).outputFiles[0].contents;
    assert.deepEqual(await readFile(path.join(root,`packages/sdk/dist/${entry}.js`)),Buffer.from(output),`source/distribution drift ${entry}`);
    hashes[entry]=sha256(output);
  }
  assert.deepEqual(JSON.parse(await readFile(path.join(root,'packages/sdk/dist/build-manifest.json'))),{schema:'zge.sdk.build.v1',hashes},'SDK build manifest drift');
  return hashes;
}
